m since the 19th century.","region":"Bangladesh","country":"Bangladesh","category":"world","base":"chhena","ingredients":["chhena","sugar"],"sweetness":4,"richness":3,"texture":"soft","tags":["heritage"],"occasions":["guests"],"is_sugar_free":false,"is_vegan":false,"is_jain":true,"is_eggless":true,"is_gluten_free":true,"allergens":["milk"],"price_unit":"1 pc","base_price":40.0,"rating":4.5,"rating_count":116,"popularity":167,"is_new":false,"is_festive":false,"image_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Porabarir_chomchom%2C_Tangail.jpg/960px-Porabarir_chomchom%2C_Tangail.jpg","image_credit":"Photo: Ferdous · CC BY-SA 4.0 · Wikimedia Commons","created_at":"2025-10-29T12:00:00+00:00","variants":[{"weight_label":"1 pc","grams":null,"price":40.0,"stock_qty":null,"sort_order":0},{"weight_label":"box of 6","grams":null,"price":225.0,"stock_qty":41,"sort_order":1},{"weight_label":"box of 12","grams":null,"price":430.0,"stock_qty":27,"sort_order":2}]},{"slug":"malva-pudding","name":"Malva Pudding","name_hi":"मालवा पुडिंग","description":"Spongy apricot pudding soaked in cream sauce.","origin_story":"A Cape Dutch dessert from South Africa.","region":"South Africa","country":"South Africa","category":"world","base":"flour","ingredients":["sponge","apricot jam","cream sauce"],"sweetness":5,"richness":4,"texture":"soft","tags":["classic"],"occasions":["guests"],"is_sugar_free":false,"is_vegan":false,"is_jain":false,"is_eggless":false,"is_gluten_free":false,"allergens":["gluten","egg","milk"],"price_unit":"1 pc","base_price":160.0,"rating":4.6,"rating_count":202,"popularity":80,"is_new":false,"is_festive":false,"image_url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/Malva_Pudding.jpg/960px-Malva_Pudding.jpg","image_credit":"Photo: Jon Mountjoy · CC BY 2.0 · Wikimedia Commons","created_at":"2026-02-26T12:00:00+00:00","variants":[{"weight_label":"1 pc","grams":null,"price":160.0,"stock_qty":65,"sort_order":0},{"weight_label":"box of 6","grams":null,"price":895.0,"stock_qty":26,"sort_order":1},{"weight_label":"box of 12","grams":null,"price":1730.0,"stock_qty":38,"sort_order":2}]}]$seed$::jsonb) as x(
    slug text, name text, name_hi text, description text, origin_story text, region text,
    country text, category text, base text, ingredients text[], sweetness smallint,
    richness smallint, texture text, tags text[], occasions text[], is_sugar_free boolean,
    is_vegan boolean, is_jain boolean, is_eggless boolean, is_gluten_free boolean,
    allergens text[], price_unit text, base_price numeric, rating numeric, rating_count int,
    popularity int, is_new boolean, is_festive boolean, image_url text, image_credit text,
    created_at timestamptz, variants jsonb)
), up as (
  insert into public.sweets as s (slug, name, name_hi, description, origin_story, region, country,
    category, base, ingredients, sweetness, richness, texture, tags, occasions, is_sugar_free,
    is_vegan, is_jain, is_eggless, is_gluten_free, allergens, price_unit, base_price, rating,
    rating_count, popularity, is_new, is_festive, image_url, image_credit, created_at)
  select slug, name, name_hi, description, origin_story, region, country, category, base,
    ingredients, sweetness, richness, texture, tags, occasions, is_sugar_free, is_vegan, is_jain,
    is_eggless, is_gluten_free, allergens, price_unit, base_price, rating, rating_count,
    popularity, is_new, is_festive, image_url, image_credit, created_at
  from data
  on conflict (slug) do update set
    name = excluded.name, name_hi = excluded.name_hi, description = excluded.description,
    origin_story = excluded.origin_story, region = excluded.region, country = excluded.country,
    category = excluded.category, base = excluded.base, ingredients = excluded.ingredients,
    sweetness = excluded.sweetness, richness = excluded.richness, texture = excluded.texture,
    tags = excluded.tags, occasions = excluded.occasions, is_sugar_free = excluded.is_sugar_free,
    is_vegan = excluded.is_vegan, is_jain = excluded.is_jain, is_eggless = excluded.is_eggless,
    is_gluten_free = excluded.is_gluten_free, allergens = excluded.allergens,
    price_unit = excluded.price_unit, base_price = excluded.base_price, rating = excluded.rating,
    rating_count = excluded.rating_count, is_new = excluded.is_new, is_festive = excluded.is_festive,
    image_url = coalesce(s.image_url, excluded.image_url),
    image_credit = coalesce(s.image_credit, excluded.image_credit)
  returning s.id, s.slug
)
insert into public.sweet_variants as v (sweet_id, weight_label, grams, price, stock_qty, sort_order)
select up.id, vv.weight_label, vv.grams, vv.price, vv.stock_qty, vv.sort_order
from up
join data d on d.slug = up.slug
cross join lateral jsonb_to_recordset(d.variants) as vv(weight_label text, grams int, price numeric,
                                                        stock_qty int, sort_order smallint)
on conflict (sweet_id, weight_label) do update set
  grams = excluded.grams, price = excluded.price, stock_qty = excluded.stock_qty,
  sort_order = excluded.sort_order;

-- Shayari (100 original lines). Replaces the whole table.
delete from public.shayari;
insert into public.shayari (sweet_id, category, occasion, text_hi, text_roman, text_en)
select s.id, x.category, x.occasion, x.text_hi, x.text_roman, x.text_en
from jsonb_to_recordset($seed$[{"slug":"rasgulla","category":null,"occasion":"purchase","text_hi":"रस में डूबा, सफ़ेद सा चाँद,\nएक उठाया तो दूजे ने खींचा हाथ।","text_roman":"Ras mein dooba, safed sa chaand,\nek uthaya toh dooje ne kheencha haath.","text_en":"A white moon soaked in syrup; pick one up and the next one tugs at your hand."},{"slug":"rasmalai","category":null,"occasion":"purchase","text_hi":"केसर की नदी में तैरती मलाई की नाव,\nचम्मच भी बोला — ज़रा धीरे से खाओ।","text_roman":"Kesar ki nadi mein tairti malai ki naav,\nchammach bhi bola — zara dheere se khaao.","text_en":"A boat of cream floating on a saffron river; even the spoon says, eat it slowly."},{"slug":"sandesh","category":null,"occasion":"purchase","text_hi":"न शोर, न ठाठ, बस नरमी की बात,\nसंदेश लाया है मीठे दिन की सौग़ात।","text_roman":"Na shor, na thaath, bas narmi ki baat,\nsandesh laaya hai meethe din ki saugaat.","text_en":"No noise, no show, just softness; sandesh brings the gift of a sweet day."},{"slug":"nolen-gurer-sandesh","category":null,"occasion":"purchase","text_hi":"सर्दी की धूप सा सुनहरा स्वाद,\nनलेन गुड़ ने रख ली दिल की याद।","text_roman":"Sardi ki dhoop sa sunehra swaad,\nnolen gur ne rakh li dil ki yaad.","text_en":"A taste golden like winter sun; nolen gur keeps a memory in the heart."},{"slug":"mishti-doi","category":null,"occasion":"purchase","text_hi":"मिट्टी के कुल्हड़ में जमी मिठास की रात,\nसुबह हुई तो दही ने कह दी दिल की बात।","text_roman":"Mitti ke kulhad mein jami mithaas ki raat,\nsubah hui toh dahi ne keh di dil ki baat.","text_en":"Sweetness set overnight in a clay pot; by morning the curd had spoken its heart."},{"slug":"chamcham","category":null,"occasion":"purchase","text_hi":"लंबा सा, प्यारा सा, नारियल की शॉल ओढ़े,\nचमचम आया तो सबने गपशप छोड़े।","text_roman":"Lamba sa, pyaara sa, nariyal ki shawl odhe,\nchamcham aaya toh sabne gapshap chhode.","text_en":"Long and lovely in a coconut shawl; when chamcham arrived, everyone stopped gossiping."},{"slug":"gulab-jamun","category":null,"occasion":"purchase","text_hi":"गुलाब की ख़ुशबू, चाशनी का दरिया,\nएक जामुन में छुपा पूरा बचपन का ज़रिया।","text_roman":"Gulab ki khushboo, chaashni ka dariya,\nek jamun mein chhupa poora bachpan ka zariya.","text_en":"Rose scent and a river of syrup; one jamun holds a whole childhood."},{"slug":"kala-jamun","category":null,"occasion":"purchase","text_hi":"रंग साँवला, दिल मीठा भरा,\nकाला जामुन बोले — देखो मुझे ज़रा।","text_roman":"Rang saanwla, dil meetha bhara,\nkaala jamun bole — dekho mujhe zara.","text_en":"Dark in colour, full of sweetness; kala jamun says, take a second look at me."},{"slug":"jalebi","category":null,"occasion":"purchase","text_hi":"घुमावदार बातें, सीधी सी मिठास,\nजलेबी कहे — उलझन में भी है ख़ास।","text_roman":"Ghumaavdaar baatein, seedhi si mithaas,\njalebi kahe — uljhan mein bhi hai khaas.","text_en":"Twisted talk, straight sweetness; jalebi says even tangles can be special."},{"slug":"imarti","category":null,"occasion":"purchase","text_hi":"फूल सी बनी, केसर में रंगी,\nइमरती आई तो थाली भी सजी।","text_roman":"Phool si bani, kesar mein rangi,\nimarti aayi toh thaali bhi saji.","text_en":"Shaped like a flower, dyed in saffron; when imarti came, the plate dressed up too."},{"slug":"rabri","category":null,"occasion":"purchase","text_hi":"परत पे परत, सब्र की कहानी,\nरबड़ी में घुली है दादी की ज़ुबानी।","text_roman":"Parat pe parat, sabr ki kahaani,\nrabri mein ghuli hai daadi ki zubaani.","text_en":"Layer upon layer, a tale of patience; grandma's stories are melted into rabri."},{"slug":"kulfi","category":null,"occasion":"purchase","text_hi":"गर्मी ने पूछा — कहाँ छुपोगे यार?\nकुल्फी बोली — मेरे पास आओ एक बार।","text_roman":"Garmi ne poochha — kahaan chhupoge yaar?\nkulfi boli — mere paas aao ek baar.","text_en":"Summer asked, where will you hide? Kulfi said, come to me just once."},{"slug":"agra-petha","category":null,"occasion":"purchase","text_hi":"शीशे सा साफ़, दिल सा सच्चा,\nपेठा आगरे का, हर मौसम अच्छा।","text_roman":"Sheeshe sa saaf, dil sa sachcha,\npetha Agre ka, har mausam achchha.","text_en":"Clear as glass, true as a heart; Agra's petha is good in every season."},{"slug":"soan-papdi","category":null,"occasion":"purchase","text_hi":"रेशा-रेशा घुले मुँह में आते,\nसोन पापड़ी वाले डिब्बे सबको भाते।","text_roman":"Resha-resha ghule munh mein aate,\nsoan papdi waale dibbe sabko bhaate.","text_en":"Thread by thread it melts in the mouth; everyone loves a soan papdi box."},{"slug":"ghewar","category":null,"occasion":"purchase","text_hi":"सावन की बूँदों सा जाली वाला ताज,\nघेवर ने रख ली तीज की लाज।","text_roman":"Saawan ki boondon sa jaali waala taaj,\nghewar ne rakh li Teej ki laaj.","text_en":"A lace crown like monsoon drops; ghewar keeps Teej's honour."},{"slug":"balushahi","category":null,"occasion":"purchase","text_hi":"परतों में छुपी है घी की कहानी,\nबालूशाही बोले — मैं हूँ शाही निशानी।","text_roman":"Paraton mein chhupi hai ghee ki kahaani,\nbalushahi bole — main hoon shaahi nishaani.","text_en":"A ghee story hidden in layers; balushahi says, I am a royal sign."},{"slug":"malpua","category":null,"occasion":"purchase","text_hi":"तवे से उतरा, चाशनी में नहाया,\nमालपुआ आया तो होली का रंग छाया।","text_roman":"Tawe se utra, chaashni mein nahaaya,\nmalpua aaya toh Holi ka rang chhaaya.","text_en":"Off the pan and bathed in syrup; when malpua arrives, Holi colours spread."},{"slug":"gujiya","category":null,"occasion":"purchase","text_hi":"आधा चाँद, अंदर मेवों का ख़ज़ाना,\nगुझिया के बिना त्योहार अधूरा माना।","text_roman":"Aadha chaand, andar mewon ka khazaana,\ngujiya ke bina tyohaar adhoora maana.","text_en":"A half moon with a treasure of nuts inside; a festival without gujiya feels incomplete."},{"slug":"peda","category":null,"occasion":"purchase","text_hi":"छोटा सा गोल, प्रसाद सा पावन,\nपेड़ा खाओ तो मन हो जाए सावन।","text_roman":"Chhota sa gol, prasad sa paavan,\npeda khaao toh man ho jaaye saawan.","text_en":"Small and round, pure like prasad; eat a peda and your heart turns to monsoon."},{"slug":"mathura-peda","category":null,"occasion":"purchase","text_hi":"कान्हा की नगरी का भूरा सा प्यार,\nएक पेड़ा और मन माखन सा तैयार।","text_roman":"Kanha ki nagri ka bhoora sa pyaar,\nek peda aur man maakhan sa taiyaar.","text_en":"The brown love of Kanha's city; one peda and the heart turns soft as butter."},{"slug":"dharwad-peda","category":null,"occasion":"purchase","text_hi":"भूनी हुई मिठास, दानेदार अंदाज़,\nधारवाड़ का पेड़ा, सबसे अलग आवाज़।","text_roman":"Bhooni hui mithaas, daanedaar andaaz,\nDharwad ka peda, sabse alag awaaz.","text_en":"Roasted sweetness with a grainy style; Dharwad's peda has a voice of its own."},{"slug":"kalakand","category":null,"occasion":"purchase","text_hi":"दाने-दाने में दूध की दुआ,\nकलाकंद खाया तो दिल बोला — वाह, क्या हुआ!","text_roman":"Daane-daane mein doodh ki dua,\nkalakand khaaya toh dil bola — waah, kya hua!","text_en":"A blessing of milk in every grain; one bite of kalakand and the heart says, wow, what happened!"},{"slug":"milk-cake","category":null,"occasion":"purchase","text_hi":"बीच में सुनहरा, किनारे पे गोरा,\nमिल्क केक का टुकड़ा कभी न लगे थोड़ा।","text_roman":"Beech mein sunehra, kinaare pe gora,\nmilk cake ka tukda kabhi na lage thoda.","text_en":"Golden in the middle, pale at the edges; a piece of milk cake never feels like enough."},{"slug":"kaju-katli","category":null,"occasion":"purchase","text_hi":"चाँदी की परत ओढ़े हीरे सी कटी,\nदीपावली हो या सोमवार, काजू कतली ही जँची।","text_roman":"Chaandi ki parat odhe heere si kati,\nDeepawali ho ya Somvaar, kaju katli hi janchi.","text_en":"Cut like a diamond, wearing silver; Deepawali or a Monday, kaju katli always fits."},{"slug":"kaju-pista-roll","category":null,"occasion":"purchase","text_hi":"काजू ने लपेटा पिस्ते को प्यार से,\nरोल बना ऐसा, बिके हर बाज़ार से।","text_roman":"Kaju ne lapeta piste ko pyaar se,\nroll bana aisa, bike har baazaar se.","text_en":"Cashew wrapped pistachio with love; such a roll sells in every market."},{"slug":"anjeer-barfi","category":null,"occasion":"purchase","text_hi":"चीनी को छुट्टी, अंजीर को काम,\nमीठा भी खाओ, सेहत को सलाम।","text_roman":"Cheeni ko chhutti, anjeer ko kaam,\nmeetha bhi khaao, sehat ko salaam.","text_en":"Sugar gets a holiday, figs get the job; eat sweet and salute your health too."},{"slug":"khajur-roll","category":null,"occasion":"purchase","text_hi":"खजूर की मिठास, मेवों की बारात,\nशुगर से डरने वालों की भी बन गई बात।","text_roman":"Khajur ki mithaas, mewon ki baaraat,\nsugar se darne waalon ki bhi ban gayi baat.","text_en":"Date sweetness with a procession of nuts; even those afraid of sugar are sorted."},{"slug":"sugar-free-kaju-katli","category":null,"occasion":"purchase","text_hi":"वही चमक, वही काजू का राज,\nबस चीनी नहीं, फिर भी पूरा अंदाज़।","text_roman":"Wahi chamak, wahi kaju ka raaj,\nbas cheeni nahin, phir bhi poora andaaz.","text_en":"Same shine, same cashew reign; just no sugar, and all the style."},{"slug":"badam-barfi","category":null,"occasion":"purchase","text_hi":"बादाम की बातें, केसर की रात,\nबर्फी ने कर दी शाही शुरुआत।","text_roman":"Badaam ki baatein, kesar ki raat,\nbarfi ne kar di shaahi shuruaat.","text_en":"Talk of almonds, a saffron night; the barfi made a royal start."},{"slug":"pista-barfi","category":null,"occasion":"purchase","text_hi":"हरा-भरा रंग, नवाबी मिज़ाज,\nपिस्ता बर्फी है मिठाइयों का ताज।","text_roman":"Hara-bhara rang, nawaabi mizaaj,\npista barfi hai mithaaiyon ka taaj.","text_en":"Lush green colour, nawabi mood; pista barfi is the crown of sweets."},{"slug":"coconut-barfi","category":null,"occasion":"purchase","text_hi":"नारियल बोला — मैं भी मीठा बन जाऊँ,\nदूध ने कहा — आ, तुझे बर्फी बनाऊँ।","text_roman":"Nariyal bola — main bhi meetha ban jaaun,\ndoodh ne kaha — aa, tujhe barfi banaaun.","text_en":"Coconut said, let me turn sweet too; milk said, come, I'll make you barfi."},{"slug":"dodha-barfi","category":null,"occasion":"purchase","text_hi":"भूरा सा रंग, पंजाबी जिगर,\nडोडा खाओ तो मुस्कान हो हर पहर।","text_roman":"Bhoora sa rang, Punjabi jigar,\ndodha khaao toh muskaan ho har pehar.","text_en":"Brown in colour with a Punjabi heart; eat dodha and smile all day."},{"slug":"pinni","category":null,"occasion":"purchase","text_hi":"सर्दी की सुबह, बेबे का हाथ,\nपिन्नी में बँधी है घर की बात।","text_roman":"Sardi ki subah, bebe da haath,\npinni mein bandhi hai ghar ki baat.","text_en":"A winter morning and mother's hand; home is tied up in a pinni."},{"slug":"gajar-ka-halwa","category":null,"occasion":"purchase","text_hi":"लाल गाजर ने दूध से की दोस्ती,\nसर्दी की शाम हो गई सबसे मीठी।","text_roman":"Laal gaajar ne doodh se ki dosti,\nsardi ki shaam ho gayi sabse meethi.","text_en":"Red carrots befriended milk; the winter evening became the sweetest."},{"slug":"moong-dal-halwa","category":null,"occasion":"purchase","text_hi":"घंटों की मेहनत, घी की बरसात,\nमूंग दाल हलवा — शादी की सौग़ात।","text_roman":"Ghanton ki mehnat, ghee ki barsaat,\nmoong dal halwa — shaadi ki saugaat.","text_en":"Hours of effort and a rain of ghee; moong dal halwa is a wedding gift."},{"slug":"sooji-halwa","category":null,"occasion":"purchase","text_hi":"सादा सा सूजी, घी में नहाया,\nप्रसाद बना तो सबको भाया।","text_roman":"Saada sa sooji, ghee mein nahaaya,\nprasad bana toh sabko bhaaya.","text_en":"Simple semolina bathed in ghee; made into prasad, it pleased everyone."},{"slug":"badam-halwa","category":null,"occasion":"purchase","text_hi":"बादाम पिसे, केसर मिले,\nहलवे के आगे सब फीके पड़े।","text_roman":"Badaam pise, kesar mile,\nhalwe ke aage sab pheeke pade.","text_en":"Almonds ground, saffron added; everything else looks pale beside this halwa."},{"slug":"boondi-laddoo","category":null,"occasion":"purchase","text_hi":"छोटी-छोटी बूँदें, बड़ा सा प्यार,\nलड्डू बँटे तो हो गया त्योहार।","text_roman":"Chhoti-chhoti boondein, bada sa pyaar,\nladdoo bante toh ho gaya tyohaar.","text_en":"Tiny drops, big love; hand out laddoos and it's a festival."},{"slug":"motichoor-laddoo","category":null,"occasion":"purchase","text_hi":"मोतियों को चूरा, केसर का रंग,\nमोतीचूर आया, ख़ुशियाँ हैं संग।","text_roman":"Motiyon ko choora, kesar ka rang,\nmotichoor aaya, khushiyaan hain sang.","text_en":"Crushed pearls in saffron colour; motichoor came, and happiness came with it."},{"slug":"besan-laddoo","category":null,"occasion":"purchase","text_hi":"भुना बेसन, घी की ख़ुशबू,\nएक लड्डू और मिट गई हर गुफ़्तगू।","text_roman":"Bhuna besan, ghee ki khushboo,\nek laddoo aur mit gayi har guftagu.","text_en":"Roasted besan, ghee aroma; one laddoo and every argument ends."},{"slug":"til-laddoo","category":null,"occasion":"purchase","text_hi":"तिल-गुड़ लो, मीठा-मीठा बोलो,\nसर्दी की धूप में दिल के दरवाज़े खोलो।","text_roman":"Til-gud lo, meetha-meetha bolo,\nsardi ki dhoop mein dil ke darwaaze kholo.","text_en":"Take sesame and jaggery, speak sweetly; open your heart in the winter sun."},{"slug":"coconut-laddoo","category":null,"occasion":"purchase","text_hi":"नारियल और गुड़ की मीठी जोड़ी,\nबप्पा भी बोले — दो और ले लो थोड़ी।","text_roman":"Nariyal aur gud ki meethi jodi,\nBappa bhi bole — do aur le lo thodi.","text_en":"Coconut and jaggery, a sweet pair; even Bappa says, take two more."},{"slug":"mohanthal","category":null,"occasion":"purchase","text_hi":"दानेदार बेसन, केसरिया शान,\nमोहनथाल है गुजरात की पहचान।","text_roman":"Daanedaar besan, kesariya shaan,\nmohanthal hai Gujarat ki pehchaan.","text_en":"Grainy besan with saffron pride; mohanthal is Gujarat's identity."},{"slug":"basundi","category":null,"occasion":"purchase","text_hi":"दूध ने सब्र किया, मिठास मिली,\nबासुंदी की कटोरी में ठंडक खिली।","text_roman":"Doodh ne sabr kiya, mithaas mili,\nbasundi ki katori mein thandak khili.","text_en":"Milk was patient and found sweetness; coolness blooms in a bowl of basundi."},{"slug":"shrikhand","category":null,"occasion":"purchase","text_hi":"दही ने छोड़ा पानी, केसर ने दी जान,\nश्रीखंड बना, पूरी हुई मेहमान।","text_roman":"Dahi ne chhoda paani, kesar ne di jaan,\nshrikhand bana, poori hui mehmaan.","text_en":"Curd let go of water, saffron gave it life; shrikhand was made and the puri became its guest."},{"slug":"modak","category":null,"occasion":"purchase","text_hi":"चावल की चादर, नारियल का दिल,\nबप्पा के मोदक से सबके चेहरे खिल।","text_roman":"Chawal ki chaadar, nariyal ka dil,\nBappa ke modak se sabke chehre khil.","text_en":"A rice-flour sheet around a coconut heart; Bappa's modak makes every face bloom."},{"slug":"puran-poli","category":null,"occasion":"purchase","text_hi":"पूरन भरा प्यार, घी से सजी,\nपूरन पोली में माँ की यादें बसी।","text_roman":"Puran bhara pyaar, ghee se saji,\npuran poli mein maa ki yaadein basi.","text_en":"Love filled with puran, dressed in ghee; mother's memories live in puran poli."},{"slug":"mysore-pak","category":null,"occasion":"purchase","text_hi":"महल की रसोई से निकला सुनहरा राज़,\nमैसूर पाक के आगे झुके हर अंदाज़।","text_roman":"Mahal ki rasoi se nikla sunehra raaz,\nMysore pak ke aage jhuke har andaaz.","text_en":"A golden secret from the palace kitchen; every style bows before Mysore pak."},{"slug":"payasam","category":null,"occasion":"purchase","text_hi":"चावल, दूध, काजू की टोली,\nपायसम ने सद्या की थाली भर दी पूरी।","text_roman":"Chawal, doodh, kaju ki toli,\npayasam ne sadya ki thaali bhar di poori.","text_en":"Rice, milk and a gang of cashews; payasam filled the whole sadya plate."},{"slug":"adhirasam","category":null,"occasion":"purchase","text_hi":"गुड़ की चमक, चावल का साथ,\nअधिरसम बोले — पुरानी है मेरी बात।","text_roman":"Gud ki chamak, chawal ka saath,\nadhirasam bole — puraani hai meri baat.","text_en":"Jaggery shine with rice for company; adhirasam says, my story is an old one."},{"slug":"double-ka-meetha","category":null,"occasion":"purchase","text_hi":"डबल रोटी ने ओढ़ी केसर की चादर,\nहैदराबाद की दावत हुई और भी बेहतर।","text_roman":"Double roti ne odhi kesar ki chaadar,\nHyderabad ki daawat hui aur bhi behtar.","text_en":"Bread wore a saffron sheet; Hyderabad's feast got even better."},{"slug":"qubani-ka-meetha","category":null,"occasion":"purchase","text_hi":"ख़ुबानी की मिठास, मलाई का ताज,\nनिज़ामी दावत का यही है राज़।","text_roman":"Khubaani ki mithaas, malai ka taaj,\nNizaami daawat ka yahi hai raaz.","text_en":"Apricot sweetness under a crown of cream; this is the secret of a Nizami feast."},{"slug":"shahi-tukda","category":null,"occasion":"purchase","text_hi":"घी में तला, रबड़ी में डूबा,\nशाही टुकड़ा — हर निवाला अजूबा।","text_roman":"Ghee mein tala, rabri mein dooba,\nshaahi tukda — har niwaala ajooba.","text_en":"Fried in ghee, drowned in rabri; shahi tukda makes every bite a wonder."},{"slug":"gur-gajak","category":null,"occasion":"purchase","text_hi":"गुड़ की खनक, तिल की बात,\nगजक बिना अधूरी सर्दी की रात।","text_roman":"Gud ki khanak, til ki baat,\ngajak bina adhoori sardi ki raat.","text_en":"The crunch of jaggery, the talk of sesame; a winter night is incomplete without gajak."},{"slug":"muzaffarnagar-gur-laddoo","category":null,"occasion":"purchase","text_hi":"अपने शहर का गुड़, अपनी मिट्टी का प्यार,\nमुज़फ़्फ़रनगर का लड्डू — मीठा हर बार।","text_roman":"Apne shehar ka gud, apni mitti ka pyaar,\nMuzaffarnagar ka laddoo — meetha har baar.","text_en":"Our city's jaggery, our soil's love; the Muzaffarnagar laddoo is sweet every time."},{"slug":"peanut-chikki","category":null,"occasion":"purchase","text_hi":"मूंगफली ने गुड़ से हाथ मिलाया,\nचिक्की बनी, बच्चों ने शोर मचाया।","text_roman":"Moongphali ne gud se haath milaaya,\nchikki bani, bachchon ne shor machaaya.","text_en":"Peanut shook hands with jaggery; chikki was born and the kids cheered."},{"slug":"phirni","category":null,"occasion":"purchase","text_hi":"कुल्हड़ में जमी चावल की चाँदनी,\nफिरनी है ईद की सबसे प्यारी रागिनी।","text_roman":"Kulhad mein jami chawal ki chaandni,\nphirni hai Eid ki sabse pyaari raagini.","text_en":"Moonlight of rice set in a clay cup; phirni is Eid's dearest melody."},{"slug":"chawal-ki-kheer","category":null,"occasion":"purchase","text_hi":"धीमी आँच, लंबी बात,\nखीर में पकती है घर की सौग़ात।","text_roman":"Dheemi aanch, lambi baat,\nkheer mein pakti hai ghar ki saugaat.","text_en":"A low flame and a long chat; home's gift cooks slowly in kheer."},{"slug":"sheer-khurma","category":null,"occasion":"purchase","text_hi":"ईद की सुबह, खजूर की मिठास,\nशीर ख़ुरमा लाया दिलों में पास।","text_roman":"Eid ki subah, khajoor ki mithaas,\nsheer khurma laaya dilon mein paas.","text_en":"An Eid morning and the sweetness of dates; sheer khurma brings hearts closer."},{"slug":"bal-mithai","category":null,"occasion":"purchase","text_hi":"पहाड़ों की ठंड, चीनी के मोती,\nबाल मिठाई बोले — मैं अल्मोड़ा की ज्योति।","text_roman":"Pahaadon ki thand, cheeni ke moti,\nbal mithai bole — main Almora ki jyoti.","text_en":"Mountain cold and pearls of sugar; bal mithai says, I am Almora's light."},{"slug":"thekua","category":null,"occasion":"purchase","text_hi":"छठ की सुबह, गुड़ का ठेकुआ,\nसूरज भी मुस्काए देख के ये जलवा।","text_roman":"Chhath ki subah, gud ka thekua,\nsooraj bhi muskaaye dekh ke ye jalwa.","text_en":"A Chhath morning and a jaggery thekua; even the sun smiles at the sight."},{"slug":"chhena-poda","category":null,"occasion":"purchase","text_hi":"जली हुई परत, नरम सा दिल,\nछेना पोड़ा से हर कोई जाए मिल।","text_roman":"Jali hui parat, naram sa dil,\nchhena poda se har koi jaaye mil.","text_en":"A burnt crust and a soft heart; everyone makes friends with chhena poda."},{"slug":"pootharekulu","category":null,"occasion":"purchase","text_hi":"काग़ज़ सी पतली, घी से भरी,\nपूथरेकुलु की परतें हैं जादू भरी।","text_roman":"Kaagaz si patli, ghee se bhari,\npootharekulu ki paratein hain jaadu bhari.","text_en":"Thin as paper, full of ghee; pootharekulu's layers are full of magic."},{"slug":"bebinca","category":null,"occasion":"purchase","text_hi":"परत-दर-परत, सब्र की मिठाई,\nगोवा की बेबिंका ने महफ़िल सजाई।","text_roman":"Parat-dar-parat, sabr ki mithaai,\nGoa ki bebinca ne mehfil sajaai.","text_en":"Layer after layer, a sweet of patience; Goa's bebinca dressed up the party."},{"slug":"mango-rasmalai","category":null,"occasion":"purchase","text_hi":"आम ने पूछा — मुझे भी मलाई में डुबाओगे?\nहमने कहा — एक बार चखोगे तो लौट आओगे।","text_roman":"Aam ne poochha — mujhe bhi malai mein dubaaoge?\nhumne kaha — ek baar chakhoge toh laut aaoge.","text_en":"Mango asked, will you dip me in cream too? We said, taste it once and you'll come back."},{"slug":"chocolate-kaju-katli","category":null,"occasion":"purchase","text_hi":"काजू ने ओढ़ा चॉकलेट का कोट,\nबच्चे बोले — ये तो है सबसे हॉट।","text_roman":"Kaju ne odha chocolate ka coat,\nbachche bole — ye toh hai sabse hot.","text_en":"Cashew put on a chocolate coat; the kids said, this one's the hottest."},{"slug":"baklava","category":null,"occasion":"purchase","text_hi":"पतली परतें, पिस्ते की बहार,\nतुर्की से आया मीठा सा यार।","text_roman":"Patli paratein, piste ki bahaar,\nTurkey se aaya meetha sa yaar.","text_en":"Thin layers and a spring of pistachios; a sweet friend from Turkey."},{"slug":"kunafa","category":null,"occasion":"purchase","text_hi":"कुरकुरी ऊपर, पिघली सी अंदर,\nकुनाफ़ा ने जीत लिया हर समंदर।","text_roman":"Kurkuri upar, pighli si andar,\nkunafa ne jeet liya har samandar.","text_en":"Crisp on top, melting inside; kunafa has conquered every sea."},{"slug":"mochi","category":null,"occasion":"purchase","text_hi":"गोल-मटोल, खिंचता सा प्यार,\nजापान से आई मोची यार।","text_roman":"Gol-matol, khinchta sa pyaar,\nJapan se aayi mochi yaar.","text_en":"Round and chubby, a stretchy kind of love; mochi came all the way from Japan."},{"slug":"churros","category":null,"occasion":"purchase","text_hi":"दालचीनी की चीनी, चॉकलेट की धार,\nचुरोस के साथ हो जाए हर शाम त्योहार।","text_roman":"Daalchini ki cheeni, chocolate ki dhaar,\nchurros ke saath ho jaaye har shaam tyohaar.","text_en":"Cinnamon sugar and a stream of chocolate; with churros every evening is a festival."},{"slug":"tiramisu","category":null,"occasion":"purchase","text_hi":"कॉफ़ी की नींद, क्रीम का ख़्वाब,\nतिरामिसु ने दिया हर सवाल का जवाब।","text_roman":"Coffee ki neend, cream ka khwaab,\ntiramisu ne diya har sawaal ka jawaab.","text_en":"Coffee's sleep and cream's dream; tiramisu answered every question."},{"slug":"french-macarons","category":null,"occasion":"purchase","text_hi":"छोटे से रंगीन, नाज़ुक से बोल,\nमैकरॉन खोलें ख़ुशियों का पोल।","text_roman":"Chhote se rangeen, naazuk se bol,\nmacaron kholein khushiyon ka pol.","text_en":"Small, colourful and soft-spoken; macarons let all the happiness out."},{"slug":"pastel-de-nata","category":null,"occasion":"purchase","text_hi":"पपड़ी कुरकुरी, कस्टर्ड सुनहरा,\nलिस्बन का तोहफ़ा, स्वाद गहरा।","text_roman":"Papdi kurkuri, custard sunehra,\nLisbon ka tohfa, swaad gehra.","text_en":"Crisp crust, golden custard; a gift from Lisbon with a deep flavour."},{"slug":"alfajores","category":null,"occasion":"purchase","text_hi":"दो बिस्कुट, बीच में मीठी सी बात,\nअल्फ़ाहोरेस से बने हर मुलाक़ात।","text_roman":"Do biscuit, beech mein meethi si baat,\nalfajores se bane har mulaaqaat.","text_en":"Two biscuits with a sweet word in between; alfajores make every meeting."},{"slug":"brigadeiro","category":null,"occasion":"purchase","text_hi":"चॉकलेट की गोली, रंगों की बरसात,\nब्रिगेडेरो से सजे जन्मदिन की रात।","text_roman":"Chocolate ki goli, rangon ki barsaat,\nbrigadeiro se saje janmdin ki raat.","text_en":"A chocolate ball in a rain of colours; brigadeiro decorates the birthday night."},{"slug":"black-forest-cake","category":null,"occasion":"purchase","text_hi":"चॉकलेट की परतें, चेरी का ताज,\nजन्मदिन का केक, आज भी वही राज।","text_roman":"Chocolate ki paratein, cherry ka taaj,\njanmdin ka cake, aaj bhi wahi raaj.","text_en":"Chocolate layers with a cherry crown; still the king of birthday cakes."},{"slug":null,"category":"laddoo","occasion":"purchase","text_hi":"गोल-गोल लड्डू, मीठी सी बात,\nजहाँ बँटे लड्डू, वहीं हो सौग़ात।","text_roman":"Gol-gol laddoo, meethi si baat,\njahaan bante laddoo, wahin ho saugaat.","text_en":"Round laddoos and sweet talk; wherever laddoos are shared, there's a gift."},{"slug":null,"category":"laddoo","occasion":"purchase","text_hi":"एक लड्डू हाथ में, दूजा नज़र में,\nमीठा रहे दिन हर पहर में।","text_roman":"Ek laddoo haath mein, dooja nazar mein,\nmeetha rahe din har pehar mein.","text_en":"One laddoo in the hand, the next in sight; may every hour of the day stay sweet."},{"slug":null,"category":"barfi","occasion":"purchase","text_hi":"चौकोर सी बर्फी, सीधा सा प्यार,\nएक टुकड़ा और खुल गया दिल का द्वार।","text_roman":"Chaukor si barfi, seedha sa pyaar,\nek tukda aur khul gaya dil ka dwaar.","text_en":"A square barfi, a straightforward love; one piece and the heart's door opens."},{"slug":null,"category":"bengali","occasion":"purchase","text_hi":"बंगाल की मिठास, छेने का कमाल,\nएक चखो तो पूछो — अगला कौन सा माल?","text_roman":"Bangal ki mithaas, chhene ka kamaal,\nek chakho toh poochho — agla kaun sa maal?","text_en":"Bengal's sweetness, chhena's magic; taste one and you'll ask, what's next?"},{"slug":null,"category":"halwa","occasion":"purchase","text_hi":"धीमी आँच पे पका सब्र का हलवा,\nहर चम्मच में घर का जलवा।","text_roman":"Dheemi aanch pe paka sabr ka halwa,\nhar chammach mein ghar ka jalwa.","text_en":"A halwa of patience cooked on low flame; every spoon shows home's charm."},{"slug":null,"category":"milk-based","occasion":"purchase","text_hi":"दूध ने सीखा मीठा होना,\nहमने सीखा इसे न खोना।","text_roman":"Doodh ne seekha meetha hona,\nhumne seekha ise na khona.","text_en":"Milk learned to be sweet; we learned never to let it go."},{"slug":null,"category":"dry-fruit","occasion":"purchase","text_hi":"मेवों की टोली, सेहत का साथ,\nतोहफ़े में दो तो बढ़े मिठास।","text_roman":"Mewon ki toli, sehat ka saath,\ntohfe mein do toh badhe mithaas.","text_en":"A gang of dry fruits with health for company; give them as a gift and sweetness grows."},{"slug":null,"category":"syrup-soaked","occasion":"purchase","text_hi":"चाशनी में डूबा, ख़ुशियों में भीगा,\nजिसने चखा, बस वहीं पे रुका।","text_roman":"Chaashni mein dooba, khushiyon mein bheega,\njisne chakha, bas wahin pe ruka.","text_en":"Dipped in syrup, soaked in joy; whoever tasted it just stayed put."},{"slug":null,"category":"fried","occasion":"purchase","text_hi":"कड़ाही से निकली सुनहरी सौग़ात,\nगरम-गरम खाओ, बने हर बात।","text_roman":"Kadaahi se nikli sunehri saugaat,\ngaram-garam khaao, bane har baat.","text_en":"A golden gift out of the kadhai; eat it hot and everything falls into place."},{"slug":null,"category":"baked","occasion":"purchase","text_hi":"भट्टी की गर्मी, मक्खन की बात,\nहर बाइट में बेकरी की सौग़ात।","text_roman":"Bhatti ki garmi, makkhan ki baat,\nhar bite mein bakery ki saugaat.","text_en":"Oven warmth and butter talk; a bakery gift in every bite."},{"slug":null,"category":"world","occasion":"purchase","text_hi":"दुनिया घूमी मिठाई की थाली में,\nस्वाद मिला हर देश की प्याली में।","text_roman":"Duniya ghoomi mithaai ki thaali mein,\nswaad mila har desh ki pyaali mein.","text_en":"The world travelled in a sweet plate; we found flavour in every country's cup."},{"slug":null,"category":"steamed","occasion":"purchase","text_hi":"भाप में पकी, नरम सी जान,\nसादगी में ही है असली शान।","text_roman":"Bhaap mein paki, naram si jaan,\nsaadgi mein hi hai asli shaan.","text_en":"Cooked in steam with a soft soul; true pride lies in simplicity."},{"slug":null,"category":"brittle","occasion":"purchase","text_hi":"कुरकुर की आवाज़, गुड़ का राज़,\nसर्दी में ये है सबसे बढ़िया साज़।","text_roman":"Kurkur ki awaaz, gud ka raaz,\nsardi mein ye hai sabse badhiya saaz.","text_en":"The sound of crunch, the secret of jaggery; the best tune of winter."},{"slug":null,"category":null,"occasion":"purchase","text_hi":"मीठा चुना है तो दिन भी मीठा जाएगा,\nस्वाद सुझाव का प्यार साथ आएगा।","text_roman":"Meetha chuna hai toh din bhi meetha jaayega,\nSwaad Sujhaav ka pyaar saath aayega.","text_en":"You've chosen sweet, so the day will be sweet too; Swaad Sujhaav's love comes along."},{"slug":null,"category":null,"occasion":"purchase","text_hi":"थाली में मिठाई, चेहरे पे मुस्कान,\nयही है हमारी दुकान की पहचान।","text_roman":"Thaali mein mithaai, chehre pe muskaan,\nyahi hai hamaari dukaan ki pehchaan.","text_en":"Sweets on the plate, a smile on the face; that's what our shop is known for."},{"slug":null,"category":null,"occasion":"welcome","text_hi":"आओ जी आओ, मीठी है ये गली,\nस्वाद सुझाव में हर मुराद है फली।","text_roman":"Aao ji aao, meethi hai ye gali,\nSwaad Sujhaav mein har muraad hai phali.","text_en":"Come in, come in, this lane is sweet; every wish comes true at Swaad Sujhaav."},{"slug":null,"category":null,"occasion":"welcome","text_hi":"दरवाज़े पे दीया, अंदर मिठास,\nपधारो जी, आज कुछ होगा ख़ास।","text_roman":"Darwaaze pe diya, andar mithaas,\npadhaaro ji, aaj kuch hoga khaas.","text_en":"A diya at the door, sweetness inside; welcome, something special will happen today."},{"slug":null,"category":null,"occasion":"welcome","text_hi":"मुज़फ़्फ़रनगर की गलियों से आई ये ख़ुशबू,\nएक बार आओ, फिर लौटोगे तू-ब-तू।","text_roman":"Muzaffarnagar ki galiyon se aayi ye khushboo,\nek baar aao, phir lautoge tu-ba-tu.","text_en":"This aroma comes from Muzaffarnagar's lanes; come once and you'll keep coming back."},{"slug":null,"category":null,"occasion":"thanks","text_hi":"शुक्रिया जी, आपका ऑर्डर है तैयार,\nमिठाई के साथ भेजा है ढेर सा प्यार।","text_roman":"Shukriya ji, aapka order hai taiyaar,\nmithaai ke saath bheja hai dher sa pyaar.","text_en":"Thank you, your order is ready; we've sent a heap of love with the sweets."},{"slug":null,"category":null,"occasion":"thanks","text_hi":"आपने भरोसा किया, हमने दिल से बनाया,\nहर डिब्बे में थोड़ा सा घर भी समाया।","text_roman":"Aapne bharosa kiya, humne dil se banaaya,\nhar dibbe mein thoda sa ghar bhi samaaya.","text_en":"You trusted us and we made it from the heart; a little bit of home fits in every box."},{"slug":null,"category":null,"occasion":"thanks","text_hi":"मीठा खाइए, मीठा बोलिए,\nफिर आइए, और दिल खोलिए।","text_roman":"Meetha khaaiye, meetha boliye,\nphir aaiye, aur dil kholiye.","text_en":"Eat sweet, speak sweet; come again and open your heart."},{"slug":null,"category":null,"occasion":"diwali","text_hi":"दीयों की कतार, मिठाई की बहार,\nइस दीपावली हो ख़ुशियों का अंबार।","text_roman":"Diyon ki kataar, mithaai ki bahaar,\nis Deepawali ho khushiyon ka ambaar.","text_en":"Rows of diyas and a spring of sweets; may this Deepawali bring a mountain of joy."},{"slug":null,"category":null,"occasion":"diwali","text_hi":"रौशनी घर में, मिठास ज़ुबान पे,\nलक्ष्मी जी बरसें हर दुकान पे।","text_roman":"Raushni ghar mein, mithaas zubaan pe,\nLakshmi ji barsein har dukaan pe.","text_en":"Light in the home, sweetness on the tongue; may Lakshmi shower blessings on every shop."},{"slug":null,"category":null,"occasion":"diwali","text_hi":"पटाख़ों से ज़्यादा चमके आपकी मुस्कान,\nस्वाद सुझाव की तरफ़ से दीपावली का सलाम।","text_roman":"Patakhon se zyaada chamke aapki muskaan,\nSwaad Sujhaav ki taraf se Deepawali ka salaam.","text_en":"May your smile sparkle more than fireworks; Deepawali greetings from Swaad Sujhaav."}]$seed$::jsonb)
  as x(slug text, category text, occasion text, text_hi text, text_roman text, text_en text)
left join public.sweets s on s.slug = x.slug;

